export const lifewellnessLittleStars = [

  { id: "lw-3-5-01", subject: "Life & Wellness", ageGroup: "3-5", band: "Little Stars", guide: "Terra", guideAnimal: "Wolf", lessonNumber: 1, title: "My Amazing Body", duration: "10-15 min",
    hook: "Your body is the most amazing machine ever built. Your heart beats 100,000 times a day without you thinking about it. Your lungs breathe in air and pull out the oxygen you need. Your brain controls everything — from wiggling your toes to dreaming while you sleep. Taking care of this incredible machine is the most important job you will ever have. Terra the Wolf runs through forests, swims in rivers, and climbs mountains — all because she takes care of her body.",
    bigIdea: "Your body is an incredible system of organs and muscles that work together to keep you alive and active — understanding how it works helps you appreciate it and motivates you to take good care of it.",
    sections: [
      { title: "Your Heart", emoji: "❤️", content: "Your heart is a muscle the size of your fist that pumps blood through your entire body. Blood carries oxygen and nutrients to every cell. Put your hand on your chest — feel that thump? That is your heart working right now. It never stops, from before you were born until the end of your life. Exercise makes your heart stronger, which is why running and playing are so important." },
      { title: "Your Lungs", emoji: "🫁", content: "Take a deep breath in. Feel your chest expand? Your lungs just filled with air. They pull oxygen out of the air and send it into your blood. Then you breathe out carbon dioxide — the waste your body does not need. You breathe about 20,000 times a day! Deep breathing calms you down because it sends extra oxygen to your brain." },
      { title: "Your Brain", emoji: "🧠", content: "Your brain is the control center for everything: moving, thinking, feeling, remembering, and even dreaming. It sends messages through your nerves at 270 miles per hour! Your brain grows most during childhood, which is why learning, playing, sleeping, and eating well are so important right now. Everything you do helps build a stronger brain." },
      { title: "Your Muscles and Bones", emoji: "💪", content: "You have over 600 muscles that help you move, and 206 bones that give your body its shape and protect your organs. Your skull protects your brain. Your ribs protect your heart and lungs. Muscles get stronger with use — every time you run, climb, or play, you are building muscle. Bones need calcium (from milk and green vegetables) to stay strong." }
    ],
    activity: { title: "Body Tour", instructions: "Do a guided body tour. Start at your head: feel your skull protecting your brain. Touch your ears — they catch sound waves. Feel your chest — your heart is beating and your lungs are breathing. Flex your arm — feel the muscle? Wiggle your fingers — count the bones (27 in each hand!). Jump up and down — feel your leg muscles working. Then draw yourself with labels: brain, heart, lungs, muscles, bones. You are walking, talking, thinking miracle." },
    quiz: [
      { question: "How many times does your heart beat each day?", answer: "About 100,000 times — it never stops pumping blood through your body", options: ["About 10 times", "About 100,000 times — it never stops pumping blood through your body", "About 1,000 times", "It only beats when you exercise"] },
      { question: "What do your lungs do?", answer: "Pull oxygen from the air into your blood and push out carbon dioxide — you breathe about 20,000 times a day", options: ["Store food", "Pull oxygen from the air into your blood and push out carbon dioxide — you breathe about 20,000 times a day", "Pump blood", "Hold water"] },
      { question: "What does your brain control?", answer: "Everything — moving, thinking, feeling, remembering, dreaming, and every body function", options: ["Only thinking", "Everything — moving, thinking, feeling, remembering, dreaming, and every body function", "Only muscles", "Nothing during sleep"] },
      { question: "How many bones do you have?", answer: "206 — they give your body shape and protect your organs", options: ["50", "206 — they give your body shape and protect your organs", "1,000", "Bones are not important"] },
      { question: "How do muscles get stronger?", answer: "By using them — every time you run, climb, play, or exercise, your muscles grow stronger", options: ["They get stronger on their own with age", "By using them — every time you run, climb, play, or exercise, your muscles grow stronger", "Only with medicine", "Muscles cannot get stronger"] }
    ],
    familyAdventure: "Do a Family Body Challenge. Feel each other's heartbeats — count beats for 15 seconds and multiply by 4 to find beats per minute (resting heart rate is usually 60-100). Then do 20 jumping jacks and check again — how much faster is your heart beating? (It speeds up to pump more oxygen to your muscles.) Then hold your breath — who can last the longest? (Usually 30-60 seconds.) Your body is communicating with you constantly — this activity helps you tune in.",
    badge: "Body Explorer", nextLesson: "lw-3-5-02"
  },

  { id: "lw-3-5-02", subject: "Life & Wellness", ageGroup: "3-5", band: "Little Stars", guide: "Terra", guideAnimal: "Wolf", lessonNumber: 2, title: "Healthy Foods Make Me Strong", duration: "10-15 min", hook: "Food is fuel — just like a car needs gas to run, your body needs food to move, think, grow, and heal. But not all fuel is equal. Some foods supercharge your body while others slow it down. Learning which foods make you strong, smart, and energized is one of the most powerful things you can do for yourself. Terra the Wolf eats natural, whole foods from the forest — and she has the energy to run for hours.", bigIdea: "Nutritious foods — fruits, vegetables, proteins, whole grains, and healthy fats — provide the energy and building blocks your body needs to grow strong, think clearly, and stay healthy.", sections: [ { title: "Food Groups", emoji: "🍎", content: "Your body needs different types of food: fruits and vegetables give vitamins and minerals. Proteins (meat, beans, eggs, nuts) build muscles. Grains (bread, rice, pasta) provide energy. Dairy (milk, cheese, yogurt) strengthens bones. Healthy fats (avocado, olive oil, nuts) help your brain. Eating a variety from all groups gives your body everything it needs." }, { title: "Superfoods for Kids", emoji: "💪", content: "Some foods are extra powerful for growing kids: berries are packed with antioxidants. Eggs have protein and brain-boosting nutrients. Sweet potatoes have vitamins that help your eyes. Yogurt has calcium for strong bones. Salmon has omega-3 fats that help your brain develop. Broccoli has more vitamin C than an orange. These are nature's multivitamins." }, { title: "Sometimes Foods", emoji: "🍬", content: "Candy, chips, soda, and fast food taste good but do not give your body what it needs. They are called sometimes foods — okay to enjoy occasionally but not as everyday fuel. Too much sugar makes you feel energized briefly then tired and cranky (a sugar crash). Your body works best on whole, natural foods." }, { title: "Water Is Life", emoji: "💧", content: "Water is the most important thing you consume. Your body is about 60% water. Water helps every organ function, carries nutrients to cells, and flushes out waste. Drink water throughout the day — not just when you feel thirsty. If your pee is pale yellow, you are well hydrated. Dark yellow means drink more water! Terra says: water is the original energy drink." } ], activity: { title: "Rainbow Plate Challenge", instructions: "Try to eat a Rainbow Plate today: at least one food of each color. Red (tomatoes, strawberries, apples), Orange (carrots, oranges, sweet potatoes), Yellow (bananas, corn, peppers), Green (broccoli, spinach, peas), Blue/Purple (blueberries, grapes, eggplant), White (cauliflower, rice, milk). Each color provides different nutrients. Draw your rainbow plate and check off each color as you eat it." }, quiz: [ { question: "Why do you need to eat different types of food?", answer: "Each food group provides different nutrients your body needs — variety ensures you get everything", options: ["You do not — one type of food is enough", "Each food group provides different nutrients your body needs — variety ensures you get everything", "Only to make meals taste better", "Different foods do not matter"] }, { question: "What are sometimes foods?", answer: "Candy, chips, and soda — they taste good but do not provide the nutrition your body needs for everyday fuel", options: ["Fruits and vegetables", "Candy, chips, and soda — they taste good but do not provide the nutrition your body needs for everyday fuel", "Foods you eat on Tuesdays", "All cooked foods"] }, { question: "Why is water so important?", answer: "Your body is 60% water — it helps organs function, carries nutrients, and flushes waste", options: ["It is not that important", "Your body is 60% water — it helps organs function, carries nutrients, and flushes waste", "Only when you exercise", "Juice is better than water"] }, { question: "What does protein help build?", answer: "Muscles — foods like meat, eggs, beans, and nuts provide protein for growth and repair", options: ["Teeth only", "Muscles — foods like meat, eggs, beans, and nuts provide protein for growth and repair", "Hair only", "Nothing important"] }, { question: "How can you tell if you are drinking enough water?", answer: "Your pee should be pale yellow — dark yellow means you need more water", options: ["You cannot tell", "Your pee should be pale yellow — dark yellow means you need more water", "Only if you feel dizzy", "You should never check"] } ], familyAdventure: "Go on a Grocery Store Adventure. Walk through the produce section and identify as many fruits and vegetables as you can. Pick one new food to try — something your child has never eaten before. Then cook a meal together using at least 4 colors of food. Discuss where each food came from (a farm, a tree, the ocean) and what nutrient it provides. When children are involved in choosing and preparing food, they are more likely to eat it. Then track water intake for one day: how many cups did each person drink? Aim for 6-8 cups.", badge: "Healthy Eater", nextLesson: "lw-3-5-03"
  },

  { id: "lw-3-5-03", subject: "Life & Wellness", ageGroup: "3-5", band: "Little Stars", guide: "Terra", guideAnimal: "Wolf", lessonNumber: 3, title: "Moving My Body Every Day", duration: "10-15 min", hook: "Jump! Run! Dance! Climb! Stretch! Your body was built to MOVE. Moving makes your heart strong, your muscles big, your bones tough, and your brain sharp. Kids who move every day sleep better, learn better, and feel happier. Terra the Wolf runs, swims, and plays with her pack every day — and she is the healthiest wolf in the forest.", bigIdea: "Daily physical activity strengthens your heart, muscles, bones, and brain — children need at least 60 minutes of active play each day for optimal health, growth, and well-being.", sections: [ { title: "Why Move?", emoji: "🏃", content: "Exercise makes your heart pump faster, delivering more oxygen and nutrients throughout your body. It builds strong muscles and bones. It releases chemicals in your brain that make you feel happy and calm. It helps you sleep better at night. It boosts your immune system so you get sick less often. There is almost nothing that exercise does not improve." }, { title: "Types of Movement", emoji: "⚡", content: "Your body needs different types of movement: cardio (running, jumping, swimming, biking) strengthens your heart and lungs. Strength (climbing, carrying, pushing) builds muscles. Flexibility (stretching, yoga, dancing) keeps your body limber and prevents injuries. Balance (standing on one foot, walking on a line) improves coordination. Mix them all for a well-rounded body." }, { title: "Making Movement Fun", emoji: "🎉", content: "Exercise does not mean boring workouts. Play tag, dance to music, ride your bike, swim at the pool, play on the playground, do obstacle courses, play sports, take family walks, climb trees (safely!), or have a living room dance party. If it gets your heart pumping and makes you smile, it counts as exercise." }, { title: "Screen Time vs Play Time", emoji: "📱", content: "Sitting and watching screens for hours makes your body stiff, weak, and tired. Your body needs at least 60 minutes of active play every day — and more is even better. For every hour of screen time, try to match it with an hour of active play. Terra says: your body is a vehicle — it works best when you drive it, not when you park it." } ], activity: { title: "Movement Menu", instructions: "Create a Movement Menu for the week: write down 7 different ways to be active, one for each day. Monday: dance party. Tuesday: bike ride. Wednesday: playground. Thursday: yoga stretches. Friday: tag or chase games. Saturday: family walk or hike. Sunday: obstacle course in the backyard. Then do today's activity right now for at least 15 minutes. Track how you feel before and after — most people feel happier and more energized after moving." }, quiz: [ { question: "How many minutes of active play do children need each day?", answer: "At least 60 minutes — and more is even better for health and happiness", options: ["10 minutes", "At least 60 minutes — and more is even better for health and happiness", "Only on weekends", "Exercise is not necessary for children"] }, { question: "What does exercise do for your brain?", answer: "It releases chemicals that make you feel happy and calm, and it helps you think and learn better", options: ["Nothing — exercise is only for your body", "It releases chemicals that make you feel happy and calm, and it helps you think and learn better", "It makes you tired and unable to think", "Only helps adults' brains"] }, { question: "What are the main types of movement your body needs?", answer: "Cardio (heart), strength (muscles), flexibility (stretching), and balance (coordination)", options: ["Only running", "Cardio (heart), strength (muscles), flexibility (stretching), and balance (coordination)", "Only lifting heavy things", "Only stretching"] }, { question: "Does playing tag count as exercise?", answer: "Yes — any activity that gets your heart pumping and makes you move counts as exercise", options: ["No — only gym workouts count", "Yes — any activity that gets your heart pumping and makes you move counts as exercise", "Only if an adult leads it", "Only organized sports count"] }, { question: "Why should you balance screen time with active play?", answer: "Too much sitting weakens your body — your muscles, bones, heart, and brain all need regular movement to stay healthy", options: ["You should not — screens are more educational", "Too much sitting weakens your body — your muscles, bones, heart, and brain all need regular movement to stay healthy", "Only to tire you out for bed", "Screen time has no effect on your body"] } ], familyAdventure: "Have a Family Fitness Day. Do a mini Olympics: event 1 — who can do the most jumping jacks in 1 minute? Event 2 — who can hold a plank the longest? Event 3 — who can balance on one foot the longest? Event 4 — who can run to the mailbox and back the fastest? Event 5 — who can touch their toes? Award silly prizes (the Golden Sneaker, the Stretchy Star). Then take a family walk or bike ride. End with gentle stretching. Your body will thank you tomorrow.", badge: "Movement Star", nextLesson: "lw-3-5-04"
  },

  { id: "lw-3-5-04", subject: "Life & Wellness", ageGroup: "3-5", band: "Little Stars", guide: "Terra", guideAnimal: "Wolf", lessonNumber: 4, title: "Sleep: My Body's Superpower", duration: "10-15 min", hook: "While you sleep, your body is incredibly busy: muscles grow, bones strengthen, your brain organizes everything you learned that day, and your immune system fights off germs. Sleep is not doing nothing — it is your body's most powerful repair and growth mode. Children who get enough sleep are happier, healthier, smarter, and taller. Terra the Wolf and her pack sleep deeply after a day of running — because rest is just as important as activity.", bigIdea: "Sleep is essential for growth, learning, immune function, and emotional regulation — children ages 3-5 need 10-13 hours of sleep each night, and good sleep habits are built through consistent routines.", sections: [ { title: "What Happens During Sleep", emoji: "🌙", content: "During sleep, your body releases growth hormone — the chemical that makes you taller and stronger. Your brain consolidates memories — organizing everything you learned into long-term storage. Your immune system strengthens — building defenses against illness. Your muscles repair — healing tiny tears from the day's activity. Sleep is when your body does its most important work." }, { title: "How Much Sleep?", emoji: "⏰", content: "Children ages 3-5 need 10-13 hours of sleep per night (including naps). Ages 6-12 need 9-12 hours. Teenagers need 8-10 hours. Adults need 7-9 hours. Getting less than your body needs affects everything: mood, learning, growth, and health. Your body tells you when it needs sleep — yawning, rubbing eyes, and crankiness are signs." }, { title: "Good Sleep Habits", emoji: "🛏️", content: "Good sleep starts with a consistent bedtime routine: same time every night, wind-down activities (reading, bathing, quiet play), dark room, cool temperature, no screens for 30-60 minutes before bed. Your brain learns to expect sleep when the routine begins — like a signal that says time to power down. Consistent routines make falling asleep faster and easier." }, { title: "Dreams", emoji: "💭", content: "When you dream, your brain is processing emotions and memories. Everyone dreams — even if you do not remember them. Some dreams are fun (flying!), some are scary (nightmares), and some are just weird. All dreams are normal. If you have a bad dream, remember: it is not real and cannot hurt you. Terra dreams of running through moonlit forests — and wakes up ready for a new day." } ], activity: { title: "Bedtime Routine Builder", instructions: "Design your perfect bedtime routine. List 5-7 steps in order: example — (1) Bath or shower, (2) Put on pajamas, (3) Brush teeth, (4) Read 2 books with a parent, (5) Talk about your day, (6) Lights out with a goodnight. Draw each step on a poster and hang it by your bed. Follow the same routine every night for a week. Track: did you fall asleep faster by the end of the week? (Almost certainly yes — consistency trains your brain for sleep.)" }, quiz: [ { question: "How many hours of sleep do children ages 3-5 need?", answer: "10-13 hours per night including naps — sleep is essential for growth and brain development", options: ["5-6 hours", "10-13 hours per night including naps — sleep is essential for growth and brain development", "Only as much as they want", "The same as adults — 7-8 hours"] }, { question: "What does your body do during sleep?", answer: "Grows taller, repairs muscles, organizes memories, and strengthens the immune system", options: ["Nothing — sleep is wasted time", "Grows taller, repairs muscles, organizes memories, and strengthens the immune system", "Only rests — nothing productive happens", "Only dreams"] }, { question: "What helps you fall asleep faster?", answer: "A consistent bedtime routine — doing the same calming activities every night trains your brain to expect sleep", options: ["Watching exciting TV right before bed", "A consistent bedtime routine — doing the same calming activities every night trains your brain to expect sleep", "Eating sugar before bed for energy", "Staying up until you collapse"] }, { question: "Are nightmares dangerous?", answer: "No — nightmares are not real and cannot hurt you; they are your brain processing emotions during sleep", options: ["Yes — nightmares can harm you physically", "No — nightmares are not real and cannot hurt you; they are your brain processing emotions during sleep", "Only if you have them every night", "Nightmares mean something is wrong"] }, { question: "Why should you avoid screens before bed?", answer: "Screen light tricks your brain into thinking it is still daytime, making it harder to fall asleep", options: ["Screens have no effect on sleep", "Screen light tricks your brain into thinking it is still daytime, making it harder to fall asleep", "Only for adults", "Screens actually help you sleep"] } ], familyAdventure: "Track Family Sleep for one week. Each person records what time they go to bed and what time they wake up. Calculate total sleep hours each night. Compare to recommendations: are you getting enough? Then implement one sleep improvement: earlier bedtime, screen-free wind-down, or a calmer routine. After a week of better sleep, discuss: did anyone notice a difference in mood, energy, or focus? The answer is almost always yes. Sleep is the most underrated health habit.", badge: "Sleep Champion", nextLesson: "lw-3-5-05"
  },

  { id: "lw-3-5-05", subject: "Life & Wellness", ageGroup: "3-5", band: "Little Stars", guide: "Terra", guideAnimal: "Wolf", lessonNumber: 5, title: "Washing Hands Keeps Me Healthy", duration: "10-15 min", hook: "Your hands touch everything: doorknobs, toys, food, pets, other people. Along the way, they pick up tiny invisible germs — bacteria and viruses too small to see. Some germs can make you sick. But there is a simple, powerful weapon against them: soap and water! Washing your hands properly is the single most effective way to prevent illness. Terra the Wolf cleans herself carefully — and so should you.", bigIdea: "Hand washing with soap and water for 20 seconds removes germs that cause illness — it is the most effective hygiene habit for preventing the spread of disease and keeping yourself and others healthy.", sections: [ { title: "What Are Germs?", emoji: "🦠", content: "Germs are tiny living things — so small you cannot see them without a microscope. Bacteria and viruses are the most common types. Some germs are harmless, and some even help your body. But others can make you sick: causing colds, flu, stomach bugs, and infections. Germs spread through touch, coughs, sneezes, and contaminated surfaces." }, { title: "How Soap Works", emoji: "🧼", content: "Soap is amazing because it breaks apart the outer layer of germs, destroying them. Water alone washes some germs away, but soap kills them. That is why washing with soap is much more effective than just rinsing with water. Rubbing your hands together creates friction that lifts germs off your skin. Then the water carries the dead germs down the drain." }, { title: "How to Wash Properly", emoji: "👐", content: "Wet your hands with clean water. Apply soap. Rub your hands together for 20 seconds — scrub the palms, the backs, between fingers, under nails, and around your thumbs. (Sing Happy Birthday twice to time 20 seconds.) Rinse under clean running water. Dry with a clean towel. Done! You just eliminated millions of germs." }, { title: "When to Wash", emoji: "⏰", content: "Wash your hands: before eating, after using the bathroom, after coughing or sneezing, after playing outside, after touching pets, after touching garbage, and before touching your face. These are the key germ-transfer moments. Making hand washing automatic at these times prevents most common illnesses. Terra says: clean paws, healthy wolf." } ], activity: { title: "Glitter Germ Experiment", instructions: "Put a small amount of glitter on your hands — the glitter represents germs. Now touch things: a doorknob, a toy, a book, a light switch. Look — glitter is everywhere you touched! That is how germs spread. Now wash your hands with just water — some glitter comes off but not all. Wash again with soap for 20 seconds — much more comes off! This is why soap matters. Then count how many surfaces the glitter spread to. Germs travel fast, but hand washing stops them." }, quiz: [ { question: "How long should you wash your hands?", answer: "At least 20 seconds with soap — about the time it takes to sing Happy Birthday twice", options: ["2 seconds is enough", "At least 20 seconds with soap — about the time it takes to sing Happy Birthday twice", "Only if they look dirty", "1 minute minimum"] }, { question: "Why is soap important?", answer: "Soap breaks apart and kills germs — water alone rinses some away but does not destroy them", options: ["Soap only makes hands smell nice", "Soap breaks apart and kills germs — water alone rinses some away but does not destroy them", "Soap is not necessary — water is enough", "Soap is only for grownups"] }, { question: "When should you wash your hands?", answer: "Before eating, after the bathroom, after coughing/sneezing, after playing outside, and after touching pets", options: ["Only before meals", "Before eating, after the bathroom, after coughing/sneezing, after playing outside, and after touching pets", "Only when they look dirty", "Once a day is enough"] }, { question: "What are germs?", answer: "Tiny organisms too small to see — including bacteria and viruses — some of which can cause illness", options: ["Visible dirt on your hands", "Tiny organisms too small to see — including bacteria and viruses — some of which can cause illness", "Only found in bathrooms", "Made up to scare children"] }, { question: "What parts of your hands should you scrub?", answer: "Palms, backs, between fingers, under nails, and around thumbs — germs hide in all these places", options: ["Only the palms", "Palms, backs, between fingers, under nails, and around thumbs — germs hide in all these places", "Only the fingertips", "Wherever the soap lands first"] } ], familyAdventure: "Do the Glitter Germ Experiment together as a family (instructions above). Then make Hand Washing a family habit check: put a sticker chart by each sink. Every time someone washes for a full 20 seconds, they add a sticker. At the end of the week, count stickers. Did hand washing frequency increase? Then track: did anyone get sick that week? Consistent hand washing families get sick significantly less often. It is one of the simplest, most effective health interventions that exists.", badge: "Germ Fighter", nextLesson: "lw-3-5-06"
  },

  { id: "lw-3-5-06", subject: "Life & Wellness", ageGroup: "3-5", band: "Little Stars", guide: "Terra", guideAnimal: "Wolf", lessonNumber: 6, title: "Feelings Are Okay", duration: "10-15 min", hook: "Happy, sad, angry, scared, excited, frustrated, proud, jealous, confused, calm — you feel ALL of these, sometimes in the same day! Every feeling is real. Every feeling is valid. No feeling is bad or wrong. What matters is not what you feel but what you DO with your feelings. Terra the Wolf feels everything deeply — and she has learned to express her feelings in healthy ways.", bigIdea: "All emotions are normal and valid — learning to identify, name, and express feelings in healthy ways builds emotional intelligence, which is essential for relationships, decision-making, and well-being.", sections: [ { title: "Naming Your Feelings", emoji: "😊", content: "The first step to handling a feeling is naming it. When you can say I feel angry instead of just exploding, you gain power over the emotion. Common feelings: happy, sad, angry, scared, excited, frustrated, proud, jealous, lonely, nervous, calm, grateful, confused, silly, and tired. Building a feelings vocabulary helps you communicate what is happening inside you." }, { title: "Where Do Feelings Come From?", emoji: "🧠", content: "Feelings come from your brain's response to situations. Something good happens → your brain sends happy signals. Something scary happens → your brain sends alert signals. Feelings are your brain's way of communicating important information: pay attention to this, this is dangerous, this person is kind, you need rest. Feelings are data, not commands." }, { title: "All Feelings Are Okay", emoji: "💚", content: "There are no bad feelings. Anger is okay — it tells you something feels unfair. Sadness is okay — it means you care about something. Fear is okay — it protects you from danger. Even jealousy is okay — it shows you what you want. The feeling itself is never wrong. What matters is how you express it: yelling and hitting are not okay. Talking about it, drawing it, or taking deep breaths are healthy expressions." }, { title: "What to Do with Big Feelings", emoji: "🌊", content: "When a feeling is overwhelming: stop and notice it (I feel angry right now). Take 3 deep breaths. Name the feeling out loud. Then choose a healthy response: talk to someone, draw your feeling, squeeze a pillow, go to a calm-down spot, or move your body. Big feelings are like big waves — they crash but always pass. Terra says: feel it, name it, let it flow through you." } ], activity: { title: "Feelings Faces", instructions: "Draw 8 faces showing different feelings: happy, sad, angry, scared, excited, frustrated, proud, and calm. Label each one. Then play Feelings Charades: one person acts out a feeling with their face and body (no words). Others guess the emotion. Then do a feelings check-in: how are you feeling RIGHT NOW? Point to the face that matches. Do this check-in at breakfast, after school, and before bed for a week. The more you practice naming feelings, the better you get at managing them." }, quiz: [ { question: "Are some feelings bad?", answer: "No — all feelings are normal and valid; what matters is how you express them, not whether you feel them", options: ["Yes — anger and sadness are bad feelings", "No — all feelings are normal and valid; what matters is how you express them, not whether you feel them", "Only positive feelings are okay", "You should try not to feel anything"] }, { question: "What should you do when you feel a big emotion?", answer: "Stop, notice it, name it, take deep breaths, and choose a healthy way to express it", options: ["Ignore it until it goes away", "Stop, notice it, name it, take deep breaths, and choose a healthy way to express it", "Scream and hit things", "Pretend you are fine"] }, { question: "Why is naming your feelings important?", answer: "It gives you power over the emotion — when you can say I feel angry you can then choose what to do about it", options: ["It is not important — feelings do not need names", "It gives you power over the emotion — when you can say I feel angry you can then choose what to do about it", "Only so adults can understand you", "Naming feelings makes them worse"] }, { question: "Is it okay to feel angry?", answer: "Yes — anger tells you something feels unfair; what matters is expressing it without hurting anyone", options: ["No — anger is always wrong", "Yes — anger tells you something feels unfair; what matters is expressing it without hurting anyone", "Only if someone is mean to you first", "Anger means you are a bad person"] }, { question: "Do big feelings last forever?", answer: "No — big feelings are like waves; they crash intensely but always pass if you let them flow through you", options: ["Yes — once you feel something, it never goes away", "No — big feelings are like waves; they crash intensely but always pass if you let them flow through you", "Only happy feelings last", "Only if you ignore them"] } ], familyAdventure: "Do a Family Feelings Check-in at dinner every night for a week. Each person shares: the best feeling they had today and the hardest feeling they had today. No one judges or tries to fix — just listen and validate. Saying that sounds like you felt really proud or I understand why that made you frustrated shows that feelings are respected in your family. Then make a Calm Down Kit together: a box with items for managing big feelings — a stress ball, crayons and paper, a favorite book, a soft toy, and a card with breathing instructions. Everyone can use it when they need to.", badge: "Feelings Expert", nextLesson: "lw-3-5-07"
  },

  { id: "lw-3-5-07", subject: "Life & Wellness", ageGroup: "3-5", band: "Little Stars", guide: "Terra", guideAnimal: "Wolf", lessonNumber: 7, title: "Taking Deep Breaths", duration: "10-15 min", hook: "When you feel angry, scared, or overwhelmed, the fastest way to calm down is to breathe. Deep, slow breaths tell your brain: I am safe. Your heart slows down, your muscles relax, and your mind clears. This is not magic — it is science. Deep breathing activates your body's calming system. Terra the Wolf takes slow, deep breaths before making any important decision.", bigIdea: "Deep breathing activates the body's relaxation response — slowing heart rate, reducing stress hormones, and calming the mind — making it the most accessible and effective self-regulation tool available.", sections: [ { title: "How Breathing Calms You", emoji: "🧘", content: "When you are stressed, your body goes into fight or flight mode: heart races, muscles tense, breathing gets fast and shallow. Deep breathing reverses this by activating the rest and digest system. Your heart slows, muscles relax, and your brain gets the message: everything is okay. This switch can happen in as little as 3-5 deep breaths." }, { title: "Belly Breathing", emoji: "🫁", content: "Belly breathing means breathing deep into your belly, not just your chest. Place your hand on your belly. Breathe in slowly through your nose for 4 counts — feel your belly push out like a balloon. Hold for 2 counts. Breathe out slowly through your mouth for 6 counts — feel your belly flatten. The out-breath should be longer than the in-breath for maximum calming effect." }, { title: "Fun Breathing Exercises", emoji: "🌬️", content: "Flower Breath: pretend to smell a beautiful flower (breathe in through your nose), then blow out a candle (breathe out through your mouth). Hot Cocoa Breath: pretend to hold a warm cup (breathe in the yummy smell), then blow on it to cool it down (slow exhale). Snake Breath: breathe in deeply, then breathe out with a long hissssss. Bunny Breath: take three quick sniffs in through your nose, one long exhale out." }, { title: "When to Breathe", emoji: "⏰", content: "Use deep breathing: when you feel angry or frustrated, when you feel scared or nervous, when you cannot fall asleep, before a test or performance, when someone is mean to you, when you feel overwhelmed, or any time you need to reset. The beauty of breathing is that you can do it anywhere, anytime — and no one even needs to know you are doing it." } ], activity: { title: "Breathing Practice", instructions: "Practice 4 breathing exercises: (1) Belly Breathing: 5 slow breaths with your hand on your belly. (2) Flower and Candle: 3 smell-the-flower, blow-the-candle breaths. (3) Square Breathing: breathe in 4 counts, hold 4, out 4, hold 4 — trace a square in the air with your finger. (4) Lion Breath: breathe in deeply, then exhale with your mouth wide open and tongue out, making a HAAA sound. Notice how calm you feel after just 2 minutes of breathing. This is a superpower you carry everywhere." }, quiz: [ { question: "How does deep breathing calm you down?", answer: "It activates your body's relaxation system — slowing your heart, relaxing muscles, and telling your brain you are safe", options: ["It does not — deep breathing has no effect", "It activates your body's relaxation system — slowing your heart, relaxing muscles, and telling your brain you are safe", "It only works for adults", "Only if someone guides you"] }, { question: "In belly breathing, should the in-breath or out-breath be longer?", answer: "The out-breath should be longer — a long exhale maximizes the calming effect", options: ["The in-breath should be longer", "The out-breath should be longer — a long exhale maximizes the calming effect", "They should be exactly equal", "It does not matter"] }, { question: "How many deep breaths does it take to start calming down?", answer: "As few as 3-5 deep breaths can begin to switch your body from stressed to calm", options: ["At least 100", "As few as 3-5 deep breaths can begin to switch your body from stressed to calm", "Only 1 breath is needed", "Deep breathing never works that quickly"] }, { question: "When should you use deep breathing?", answer: "Any time you feel angry, scared, nervous, overwhelmed, or need to reset — it works anywhere, anytime", options: ["Only during yoga class", "Any time you feel angry, scared, nervous, overwhelmed, or need to reset — it works anywhere, anytime", "Only at bedtime", "Only when an adult tells you to"] }, { question: "What is belly breathing?", answer: "Breathing deep into your belly so it expands like a balloon — not shallow chest breathing", options: ["Breathing as fast as possible", "Breathing deep into your belly so it expands like a balloon — not shallow chest breathing", "Holding your breath until your belly hurts", "Only breathing through your mouth"] } ], familyAdventure: "Start and end each day with 3 deep breaths as a family for one week. In the morning: stand together, 3 belly breaths, set an intention for the day. At bedtime: lie down, 5 slow breaths, each person says one thing they are grateful for. Track how this simple practice affects the family's mood and stress levels. Then teach deep breathing to a friend or neighbor — the best way to master a skill is to teach it. Terra says: the breath is always available, always free, and always powerful.", badge: "Breathing Master", nextLesson: "lw-3-5-08"
  },

  { id: "lw-3-5-08", subject: "Life & Wellness", ageGroup: "3-5", band: "Little Stars", guide: "Terra", guideAnimal: "Wolf", lessonNumber: 8, title: "Brushing Teeth and Staying Clean", duration: "10-15 min", hook: "Your teeth chew food, shape your smile, and help you speak clearly. But tiny bacteria in your mouth feed on leftover food and produce acid that causes cavities. Brushing and flossing protect your teeth from decay. Bathing keeps your skin clean and healthy. Personal hygiene — keeping your body clean — is how you prevent illness and feel your best. Terra the Wolf grooms herself every day to stay healthy and comfortable.", bigIdea: "Personal hygiene — brushing teeth, bathing, and keeping clean — prevents illness, protects your body, and helps you feel confident and comfortable in daily life.", sections: [ { title: "Brushing Teeth", emoji: "🦷", content: "Brush twice a day: morning and night. Use a pea-sized amount of fluoride toothpaste. Brush for 2 minutes — 30 seconds for each quadrant (upper right, upper left, lower right, lower left). Brush the front, back, and chewing surface of every tooth. Do not forget your tongue — bacteria live there too. Brushing prevents cavities, gum disease, and bad breath." }, { title: "Flossing", emoji: "🪥", content: "Flossing cleans between teeth where your toothbrush cannot reach. If you skip flossing, you are missing about 35% of each tooth's surface. Floss once a day — gently slide the floss between each pair of teeth and curve it around each tooth in a C shape. Flossing might seem tedious, but it prevents the cavities and gum disease that happen between teeth." }, { title: "Bathing and Washing", emoji: "🛁", content: "Bathing cleans your skin of dirt, sweat, and bacteria. Wash your body with soap, paying attention to areas that sweat: underarms, feet, and groin. Wash your hair regularly with shampoo. Dry off completely after bathing — moisture can cause skin irritation. Clean skin prevents rashes, infections, and body odor." }, { title: "Other Hygiene Habits", emoji: "✨", content: "Clip fingernails and toenails regularly — dirt and germs hide under long nails. Wash your face morning and night. Cover your mouth when you cough or sneeze (use your elbow, not your hand). Wear clean clothes. Change underwear daily. These habits keep your body clean, healthy, and comfortable. Terra says: a clean body is a healthy body." } ], activity: { title: "Hygiene Checklist", instructions: "Make a daily Hygiene Checklist poster. Include: brush teeth (morning), brush teeth (night), floss, bath or shower, wash hands, clean clothes, comb hair. Put it in the bathroom. Each day, check off completed tasks. At the end of the week, celebrate a full checklist. Then practice brushing: put a timer on for 2 full minutes and brush — most people are surprised how long 2 minutes actually is. Then practice covering a cough with your elbow — do it 5 times until it feels natural." }, quiz: [ { question: "How long should you brush your teeth?", answer: "2 minutes — 30 seconds for each quadrant of your mouth", options: ["10 seconds", "2 minutes — 30 seconds for each quadrant of your mouth", "Just a few quick strokes", "5 minutes minimum"] }, { question: "Why is flossing important?", answer: "It cleans between teeth where your toothbrush cannot reach — about 35% of each tooth's surface", options: ["It is not important — brushing is enough", "It cleans between teeth where your toothbrush cannot reach — about 35% of each tooth's surface", "Only if your dentist says so", "Only adults need to floss"] }, { question: "How should you cover a cough?", answer: "With your elbow — not your hand, because your hand then spreads germs to everything you touch", options: ["With your hand", "With your elbow — not your hand, because your hand then spreads germs to everything you touch", "You do not need to cover it", "Only if someone is nearby"] }, { question: "How often should you brush your teeth?", answer: "Twice a day — morning and night", options: ["Once a week", "Twice a day — morning and night", "Only when they feel dirty", "Three times a day"] }, { question: "Why is bathing important?", answer: "It cleans your skin of dirt, sweat, and bacteria — preventing rashes, infections, and body odor", options: ["Only to smell nice", "It cleans your skin of dirt, sweat, and bacteria — preventing rashes, infections, and body odor", "It is not necessary if you do not look dirty", "Only before special events"] } ], familyAdventure: "Do a Hygiene Audit together. Each person rates their hygiene habits honestly: do you brush for a full 2 minutes? (Time it and find out.) Do you floss daily? Do you wash your hands every time you should? Then pick one hygiene habit to improve this week. Track progress. Then do the Tooth Brushing Timer Challenge: play a 2-minute song and brush for the entire duration. Find a fun brushing song your child loves — music makes the 2 minutes fly by. Clean teeth, clean body, healthy life.", badge: "Hygiene Hero", nextLesson: "lw-3-5-09"
  },

  { id: "lw-3-5-09", subject: "Life & Wellness", ageGroup: "3-5", band: "Little Stars", guide: "Terra", guideAnimal: "Wolf", lessonNumber: 9, title: "Safety First: At Home and Outside", duration: "10-15 min", hook: "Your world is full of amazing things to explore — but some things can be dangerous if you are not careful. Hot stoves burn. Busy streets have fast cars. Deep water can be scary if you cannot swim. Learning safety rules is not about being afraid — it is about being smart. Smart explorers know the risks and take precautions. Terra the Wolf teaches her pups safety rules from their first day — because knowledge protects better than fear.", bigIdea: "Safety awareness — knowing potential dangers at home, outside, and around water — and following safety rules prevents injuries and protects your life and the lives of others.", sections: [ { title: "Home Safety", emoji: "🏠", content: "Hot stoves and ovens can burn — do not touch without a grownup. Sharp objects (knives, scissors) can cut — handle carefully. Medicines look like candy but can be dangerous — never take any without a grownup. Electrical outlets can shock — do not put things in them. Stairs can cause falls — hold the railing. Knowing these dangers helps you navigate your home safely." }, { title: "Outside Safety", emoji: "🚸", content: "Always look both ways before crossing a street — cars cannot stop instantly. Stay on sidewalks when walking near roads. Wear a helmet when biking, skating, or riding a scooter. Never go with a stranger — if someone you do not know asks you to go with them, say NO, run, and tell a trusted adult. Stay where your parents can see you in public places." }, { title: "Water Safety", emoji: "🏊", content: "Never swim alone — always have a grownup watching. Stay away from deep water until you are a strong swimmer. Wear a life jacket on boats. Do not run near pools — wet surfaces are slippery. If you see someone struggling in water, do NOT jump in — call for help or throw something that floats. Water is wonderful but requires respect." }, { title: "Emergency Knowledge", emoji: "🚨", content: "Know your full name, your parents' names, your address, and your phone number. Know how to call 911 in an emergency. Know what an emergency IS: fire, someone badly hurt, someone not breathing, someone in danger. Practice saying your address and phone number until you know them by heart. This knowledge could save a life — maybe yours. Terra says: preparation is the best protection." } ], activity: { title: "Safety Scavenger Hunt", instructions: "Walk through your home and identify 5 potential dangers: hot appliances, sharp objects, slippery floors, stairs, cleaning supplies. For each, discuss the safety rule. Then go outside and identify 5 outdoor dangers: the street, a pool or pond, uneven surfaces, high places, unfamiliar animals. Then practice emergency information: say your full name, address, phone number, and parents' names out loud until you have them memorized. Finally, practice calling 911 on a play phone — what do you say? (My name is ___, I need help because ___, I am at ___.) This practice could save a life." }, quiz: [ { question: "What should you do before crossing a street?", answer: "Look both ways — left, right, then left again — because cars can come from either direction", options: ["Just walk across quickly", "Look both ways — left, right, then left again — because cars can come from either direction", "Only look left", "Wait for someone else to cross first and follow them"] }, { question: "What should you do if a stranger asks you to go with them?", answer: "Say NO, run away, and immediately tell a trusted adult", options: ["Go with them if they seem nice", "Say NO, run away, and immediately tell a trusted adult", "Ask them why first", "Only go if they have candy"] }, { question: "Why should you never swim alone?", answer: "Because if something goes wrong in the water, you need someone there to help — a grownup should always be watching", options: ["Swimming alone is fine if you are a good swimmer", "Because if something goes wrong in the water, you need someone there to help — a grownup should always be watching", "Only little kids need supervision", "Solo swimming builds confidence"] }, { question: "What number do you call in an emergency?", answer: "911 — for fire, serious injuries, someone not breathing, or anyone in danger", options: ["411", "911 — for fire, serious injuries, someone not breathing, or anyone in danger", "123", "Your parents' cell phone only"] }, { question: "What information should you have memorized for emergencies?", answer: "Your full name, parents' names, home address, and a parent's phone number", options: ["Just your first name", "Your full name, parents' names, home address, and a parent's phone number", "Your favorite color", "Nothing — adults handle emergencies"] } ], familyAdventure: "Do a Family Safety Drill. Practice: (1) Fire drill — what is your escape plan? Where do you meet outside? Walk through it. (2) Address and phone number quiz — can your child recite them? (3) Stranger safety role play — practice saying no, running, and telling a trusted adult. (4) Water safety review — if you have a pool or live near water, review the rules. (5) 911 practice — role play calling for different emergencies. These 30 minutes of practice could prevent a lifetime of regret. Safety is love in action.", badge: "Safety Star", nextLesson: "lw-3-5-10"
  },

  { id: "lw-3-5-10", subject: "Life & Wellness", ageGroup: "3-5", band: "Little Stars", guide: "Terra", guideAnimal: "Wolf", lessonNumber: 10, title: "I Love Who I Am", duration: "10-15 min", hook: "You are the only YOU in the entire universe. No one else has your exact smile, your exact laugh, your exact ideas, or your exact combination of talents. You are not meant to be like anyone else — you are meant to be the best version of yourself. Loving who you are is not bragging — it is the foundation of a happy, confident, healthy life. Terra the Wolf stands tall and proud because she knows exactly who she is.", bigIdea: "Self-love and self-acceptance are the foundation of well-being — appreciating your unique qualities, being kind to yourself, and knowing your inherent worth builds confidence, resilience, and the ability to love others well.", sections: [ { title: "You Are Unique", emoji: "⭐", content: "Your fingerprints are different from every other person who has ever lived. Your voice is unique. Your face is unique. Your thoughts are unique. Your combination of interests, talents, fears, and dreams has never existed before and will never exist again. You are literally one of a kind. That is not just a nice saying — it is scientific fact." }, { title: "Loving Your Whole Self", emoji: "💕", content: "Loving yourself means accepting all of you — not just the parts you think are cool. Your strengths AND your challenges. Your successes AND your mistakes. Your confident days AND your shy days. You do not have to be perfect to be lovable. You are lovable RIGHT NOW, exactly as you are. Self-love is not about thinking you are better than others — it is about knowing you are worthy, just like everyone else." }, { title: "Being Kind to Yourself", emoji: "💛", content: "The way you talk to yourself matters. When you make a mistake, do you say I am so stupid or do you say everyone makes mistakes — I will try again? The second voice is self-compassion, and it helps you bounce back faster. Treat yourself the way you would treat your best friend — with kindness, patience, and encouragement." }, { title: "Confidence Is Quiet", emoji: "🦁", content: "True confidence is not being the loudest or thinking you are better than everyone. True confidence is knowing your worth without needing to prove it. It is trying new things even when you might fail. It is being yourself even when others are different. It is standing up for what is right even when it is hard. Terra says: the wolf who knows who she is does not need to prove it to anyone." } ], activity: { title: "My Amazing Self Portrait", instructions: "Draw a self-portrait — not just your face, but everything that makes you YOU. Around your drawing, write or draw: 3 things you love about yourself, 3 things you are good at, 3 things you enjoy, 1 challenge you are working on (to show self-acceptance), and 1 thing you are proud of. Then look at your portrait and say out loud: I am amazing exactly as I am. Frame it or hang it where you will see it every day. Seeing your own worth on paper reinforces it in your heart." }, quiz: [ { question: "Are you meant to be like anyone else?", answer: "No — you are meant to be the best version of yourself, and your unique combination of qualities has never existed before", options: ["Yes — you should try to be like successful people", "No — you are meant to be the best version of yourself, and your unique combination of qualities has never existed before", "Only like your parents", "Yes — being different is bad"] }, { question: "Does self-love mean thinking you are better than others?", answer: "No — self-love means knowing you are worthy, just like everyone else — it is about self-acceptance, not superiority", options: ["Yes — self-love means being the best", "No — self-love means knowing you are worthy, just like everyone else — it is about self-acceptance, not superiority", "Self-love is selfish", "Only adults should practice self-love"] }, { question: "What should you say to yourself when you make a mistake?", answer: "Everyone makes mistakes — I will try again — treat yourself with the same kindness you would give a friend", options: ["I am so stupid and I can never do anything right", "Everyone makes mistakes — I will try again — treat yourself with the same kindness you would give a friend", "I should give up so I do not make more mistakes", "Nothing — pretend it did not happen"] }, { question: "What is true confidence?", answer: "Knowing your worth without needing to prove it — being yourself, trying new things, and standing up for what is right", options: ["Being the loudest and most popular person", "Knowing your worth without needing to prove it — being yourself, trying new things, and standing up for what is right", "Never being scared or nervous", "Winning everything"] }, { question: "Do you have to be perfect to be lovable?", answer: "No — you are lovable right now, exactly as you are, with all your strengths and challenges", options: ["Yes — only perfect people are lovable", "No — you are lovable right now, exactly as you are, with all your strengths and challenges", "Only if you try really hard", "Only your family has to love you"] } ], familyAdventure: "Hold a Family Appreciation Circle. Sit together. Take turns: each person looks at one family member and says three specific things they love and appreciate about them. Not generic compliments — specific ones: I love how you always hug me when I am sad. I appreciate that you make dinner every night. I love your silly dance moves. Receiving specific appreciation fills your emotional tank like nothing else. Then each person says one thing they love about THEMSELVES. Self-love modeled in the family becomes self-love carried into the world. Terra the Wolf is immensely proud of every young person who completed the Little Stars Life & Wellness journey. You know how to fuel your body, move it, rest it, clean it, calm it, and love it. Your body and mind are your most precious gifts — treat them with the care they deserve.", badge: "Self-Love Champion", nextLesson: null
  },

];

export default lifewellnessLittleStars;
